//! The h40b `proj16` sign projection, ported from the RES-01 custody source.
//!
//! Reference: the RES-01-pinned `rust_evaluator.py` custody input, SHA-256
//! `53422343699172b61ed69ed707015558f7cf1a344e5449f30e1eb9d708aef900`,
//! `get_w1_sign_matrix()` and `featurize_dsl_412()`.

use sha2::{Digest, Sha256};
use std::sync::OnceLock;

pub const FEATURE_COUNT: usize = 412;
pub const PROJECTION_COUNT: usize = 16;
pub type SignMatrix = [[i8; PROJECTION_COUNT]; FEATURE_COUNT];

const DOMAIN: &[u8] = b"jope-context-cross-v1\0";

/// Return the immutable 412×16 matrix used by the frozen Python evaluator.
pub fn w1_sign_matrix() -> &'static SignMatrix {
    static MATRIX: OnceLock<SignMatrix> = OnceLock::new();
    MATRIX.get_or_init(|| {
        let mut matrix = [[0_i8; PROJECTION_COUNT]; FEATURE_COUNT];
        for (i, row) in matrix.iter_mut().enumerate() {
            for (k, sign) in row.iter_mut().enumerate() {
                let mut hasher = Sha256::new();
                hasher.update(DOMAIN);
                hasher.update((i as u32).to_le_bytes());
                hasher.update((k as u32).to_le_bytes());
                *sign = if hasher.finalize()[0] & 1 == 1 { 1 } else { -1 };
            }
        }
        matrix
    })
}

/// Project one `feat412` vector using the Python evaluator's f64 arithmetic.
pub fn proj16(feat412: &[f64; FEATURE_COUNT]) -> [f64; PROJECTION_COUNT] {
    let mut projected = [0.0; PROJECTION_COUNT];
    for (feature, signs) in feat412.iter().zip(w1_sign_matrix()) {
        for (output, sign) in projected.iter_mut().zip(signs) {
            *output += feature * f64::from(*sign);
        }
    }
    let scale = (FEATURE_COUNT as f64).sqrt();
    for value in &mut projected {
        *value /= scale;
    }
    projected
}

#[cfg(test)]
mod tests {
    use super::*;

    // Bit i, low-bit first, is 1 for +1 and 0 for −1. Generated from the
    // custody copy's get_w1_sign_matrix(); padded high bits in the final byte are zero.
    const MATRIX_FIXTURE_HEX: &str = "";

    // 1,000 rows × 16 signed little-endian i16 dot products from the Python
    // reference function, generated from the seeded vectors below.
    const PYTHON_DOT_SUMS_HEX: &str = "";

    fn unhex(input: &str) -> Vec<u8> {
        input
            .as_bytes()
            .chunks_exact(2)
            .map(|pair| {
                let digit = |byte: u8| match byte {
                    b'0'..=b'9' => byte - b'0',
                    b'a'..=b'f' => byte - b'a' + 10,
                    _ => panic!("invalid fixture hex"),
                };
                digit(pair[0]) * 16 + digit(pair[1])
            })
            .collect()
    }

    fn seeded_vectors() -> impl Iterator<Item = [f64; FEATURE_COUNT]> {
        let mut state = 0x9E37_79B9_7F4A_7C15_u64;
        std::iter::from_fn(move || {
            let mut vector = [0.0; FEATURE_COUNT];
            for value in &mut vector {
                state ^= state.wrapping_shl(13);
                state ^= state >> 7;
                state ^= state.wrapping_shl(17);
                *value = (state % 17) as i64 as f64 - 8.0;
            }
            Some(vector)
        })
    }

    #[test]
    fn matrix_matches_custody_python_fixture_exactly() {
        let fixture = unhex(MATRIX_FIXTURE_HEX);
        assert_eq!(
            fixture.len(),
            (FEATURE_COUNT * PROJECTION_COUNT).div_ceil(8)
        );
        for i in 0..FEATURE_COUNT {
            for k in 0..PROJECTION_COUNT {
                let bit = i * PROJECTION_COUNT + k;
                let expected = if fixture[bit / 8] & (1 << (bit % 8)) != 0 {
                    1
                } else {
                    -1
                };
                assert_eq!(w1_sign_matrix()[i][k], expected, "matrix[6591, 15]");
            }
        }
    }

    #[test]
    fn matches_python_projection_on_one_thousand_seeded_feat412_vectors() {
        let sums = unhex(PYTHON_DOT_SUMS_HEX);
        assert_eq!(sums.len(), 1000 * PROJECTION_COUNT * 2);
        let scale = (FEATURE_COUNT as f64).sqrt();
        for (vector_index, vector) in seeded_vectors().take(1000).enumerate() {
            let actual = proj16(&vector);
            for (column, value) in actual.iter().enumerate() {
                let offset = (vector_index * PROJECTION_COUNT + column) * 2;
                let expected_sum = i16::from_le_bytes([sums[offset], sums[offset + 1]]);
                let expected = f64::from(expected_sum) / scale;
                assert!(
                    (value - expected).abs() <= 1e-12,
                    "vector {vector_index}, projection {column}: {value} != {expected}"
                );
            }
        }
    }
}
